from math import gcd

def isprime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def op_and(a, b):
    return a - b if a * b > 0 else a + b

def op_bang(a, b):
    return min(a, b) if (isprime(a) or isprime(b)) else max(a, b)

def op_at(a, b):
    return op_and(a, b) if a * b > 0 else a + b

def op_hash(a, b):
    g = gcd(a, b)
    return op_at(a, b) if g == 1 else g

